mapper.update:
UPDATE borrow_record
SET status = #{status}, returned_at = #{returnedAt}, operator_id = #{operatorId}
WHERE id = #{id} AND status != 'RETURNED'

mapper.select:
SELECT r.id, r.user_id, r.book_id, r.copy_id, r.borrow_date, r.expected_due_date, r.returned_at,
       r.status, r.renew_count, r.operator_id, r.created_at, r.updated_at, b.name AS book_name
FROM borrow_record r
JOIN books b ON b.id = r.book_id
WHERE r.user_id = #{userId}
 AND r.status = #{status} 
ORDER BY r.id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM borrow_record
WHERE user_id = #{userId}
 AND status = #{status}

SELECT r.id, r.user_id, r.book_id, r.copy_id, r.borrow_date, r.expected_due_date, r.returned_at, r.status, r.renew_count, r.operator_id, r.created_at, r.updated_at, b.name AS book_name, u.user_name AS user_name FROM borrow_record r JOIN books b ON b.id = r.book_id JOIN users u ON u.id = r.user_id
u.user_name = #{userName}
ORDER BY r.id DESC LIMIT #{offset}, #{size}

SELECT 
FROM borrow_record
WHERE status = 'BORROWED' AND expected_due_date >= #{from} AND expected_due_date < #{to}

SELECT 
FROM borrow_record
WHERE status = 'BORROWED' AND expected_due_date < #{now}
